/**
 * Cameras flown by input, raylib's CAMERA_FREE and CAMERA_FIRST_PERSON (UpdateCamera): a 3D
 * camera actor (wgf_camera3d.h) given a mode is turned and moved each frame, before the frame
 * callback, by the keyboard, the mouse, and the pads. At most 64 cameras have a mode or a
 * setting.
 *
 *   the mouse            looks: yaw and pitch, the pitch held just short of straight up or
 *                        down; the pointer is locked while it looks (wgf_mouse_set_locked),
 *                        and a click locks it again once the platform let it go (Escape in
 *                        a browser)
 *   the right stick      looks, at the turn speed
 *   W A S D, the arrows  move forward, left, back, and right; the left stick too
 *   Space or E           FREE: up (the world's +y); a pad's right bumper too
 *   Left Control or Q    FREE: down; a pad's left bumper too
 *
 * FREE moves where it looks; FIRST_PERSON moves on the ground plane, its height kept (what
 * the program sets it to: stairs, a jump). Every pad is read, the one pushed furthest
 * winning. Keys aren't read while the keyboard is captured, and the mouse doesn't look while
 * the pointer is (wgf_input.h: a UI has it). The camera's position is read each frame, so the
 * program may move it; it is turned only by the look below while it flies. Every flown
 * camera moves by the same input, so fly one at a time; a camera that also follows
 * (wgf_follow.h) is placed by both.
 */
export const WGF_FLY_MODE_NONE = 0;
export const WGF_FLY_MODE_FREE = 1;
export const WGF_FLY_MODE_FIRST_PERSON = 2;

/**
 * Cameras that follow, helix-legacy's CameraFollow2D, CameraFollow3D, and Orbit3D: a camera
 * actor (wgf_camera2d.h, wgf_camera3d.h) given a target actor is moved each frame, before
 * the frame callback, to follow where the target is drawn. At most 64 cameras follow.
 *
 * A 2D camera centers the view on a point that follows the target: the target moves freely
 * inside a dead zone around it, and when it leaves, the point catches up, smoothed; the
 * view is kept inside its bounds when it has them (the presentation's visible area, over
 * the camera's zoom, is what must fit).
 *
 * A 3D camera sits at its offset from a point that follows the target the same way (a dead
 * zone of width across and height up, and smoothing), and looks at the point: in CHASE the
 * offset is turned with the target's heading (its turn about y), swinging round to it
 * smoothed, so it stays behind a car; in FIXED it isn't turned; in ORBIT it is the orbit's
 * (a yaw, a pitch, and a distance the program sets, from a stick or the pointer).
 *
 * Either shakes: trauma (0 to 1) added by shake and lost over time, the view thrown by its
 * square so small shakes are gentle, as helix's.
 */
export const WGF_FOLLOW_MODE_CHASE = 0;
export const WGF_FOLLOW_MODE_FIXED = 1;
export const WGF_FOLLOW_MODE_ORBIT = 2;

/**
 * A light: an actor that lights the stage it is on (wgf_stage3d.h), placed and aimed with
 * the actor calls (wgf_actor_look_at): a light shines down its -z. Lights work as
 * libwgt's (wgrender's):
 *
 * - Nothing is lit implicitly: a stage with no lights and no ambient is black.
 * - Each model is lit by the up to 8 lights reaching it most (their brightness, and
 *   their falloff at its box); point and spot lights whose range doesn't reach a model
 *   are skipped for it.
 * - A light shines while it is enabled (with everything above it) and visible
 *   (wgf_actor.h): hiding it turns it off and leaves its children as they are, a lamp's
 *   bulb model under it, say.
 * - Parameters follow glTF's KHR_lights_punctual, and shading glTF's materials
 *   (wgf_material.h), so lights from glTF tools look the same here. Light colors are
 *   sRGB; lighting happens in linear space. A white directional light of intensity pi
 *   (about 3) lights a white, rough, non-metal surface facing it fully. Point and spot
 *   lights fall off with the inverse square of distance and fade smoothly to nothing at
 *   their range (0: no limit).
 * - Setters store values even where they don't apply to the light's type (a range on a
 *   directional light).
 * - Shadows (below) are a directional or spot light's, set on per light.
 */
export const WGF_LIGHT_TYPE_DIRECTIONAL = 0;
export const WGF_LIGHT_TYPE_POINT = 1;
export const WGF_LIGHT_TYPE_SPOT = 2;

/**
 * How a game's design is fitted to the window or the screen (Godot's stretch modes
 * and aspects are the prior art). A game is written for a design resolution, and its
 * logical coordinates stay the design's at any window size and in fullscreen: drawing,
 * 2D stages, the UI, the pointer and touches (mapped back into them), and an autopilot's
 * mouse. The same on the desktop, in a resized browser window, and in fullscreen.
 *
 *   NONE     the default: logical pixels are the window's (a framebuffer pixel over the
 *            DPI scale), and the visible area is the window
 *   STRETCH  the design scaled to the window on each axis apart, its aspect lost
 *   FIT      scaled alike on both axes, as large as it fits whole, centered; the rest
 *            are bars (wgf_presentation_set_bar_color), nothing drawn in them
 *   FILL     scaled alike, as small as covers the window, centered; what is past the
 *            window's edges is cropped
 *   EXPAND   scaled as FIT is, but the visible area grows past the design to the
 *            window's edges, centered on it: the design is the least the game shows,
 *            and a UI anchored to the visible area's edges stays at them
 *   INTEGER  as FIT, at a whole number of framebuffer pixels to a logical one (at
 *            least 1), for pixel art; bars around it
 *
 * Set any time; it takes effect at the next frame. A program that never sets a mode
 * links none of its fitting. Natively, a window whose size the program didn't set
 * (wgf_window_set_size) opens at the design size. False for a size under 1 (but for
 * NONE, which takes none) or a mode that isn't one.
 */
export const WGF_PRESENTATION_MODE_NONE = 0;
export const WGF_PRESENTATION_MODE_STRETCH = 1;
export const WGF_PRESENTATION_MODE_FIT = 2;
export const WGF_PRESENTATION_MODE_FILL = 3;
export const WGF_PRESENTATION_MODE_EXPAND = 4;
export const WGF_PRESENTATION_MODE_INTEGER = 5;

