/**
 * Components: the simulation's data on an actor -- any actor, of any kind, a 2D stage's UI
 * actors and cameras included -- run each tick by libwgf's systems (wgf_world.h). One kind
 * of object, the actor (SPEC.md), Godot's tree with Unity's components: what an actor draws
 * is its kind (a shape, a sprite, a model); what moves it, bounds it, ages it, and finds
 * what it overlaps are components on it; what the program does with it are its behaviors
 * (wgf_behavior.h), several to an actor.
 *
 * An actor with a component or a behavior is simulated (wgf_actor_snap): its transform is
 * set and read at the tick rate, and it is drawn between its last two ticks, so it moves
 * smoothly at any frame rate. Its components go when it does (wgf_actor_destroy), and a
 * system that ends it (a lifetime run out, bounds of DESTROY) destroys the actor, with
 * everything under it, after the tick's systems have run.
 */
export const WGF_COMPONENT_NONE = 0;
export const WGF_COMPONENT_MOTION = 1;
export const WGF_COMPONENT_BOUNDS = 2;
export const WGF_COMPONENT_LIFETIME = 3;
export const WGF_COMPONENT_COLLIDER = 4;
export const WGF_COMPONENT_VOICE = 5;
export const WGF_COMPONENT_BODY = 6;
export const WGF_COMPONENT_VEHICLE = 7;
export const WGF_COMPONENT_BODY2D = 8;

/**
 * Bounds (WGF_COMPONENT_BOUNDS): a rectangle in the actor's parent's space, x and y,
 * and what happens to an actor whose position leaves it, by more than its margin, each
 * tick after motion. Defaults: 0, 0, 800 by 600, WRAP, a margin of 0. Every call is false
 * (or 0) for an actor without bounds.
 */
export const WGF_BOUNDS_MODE_WRAP = 0;
export const WGF_BOUNDS_MODE_CLAMP = 1;
export const WGF_BOUNDS_MODE_DESTROY = 2;

/**
 * A collider (WGF_COMPONENT_COLLIDER): a shape about the actor's position, in its parent's
 * space, that overlaps others as a trigger: each tick, after motion and bounds, two colliders
 * that start to overlap raise TRIGGER_ENTER and two that stop raise TRIGGER_EXIT
 * (wgf_world.h), told to each. They overlap only where one's layer meets the other's mask:
 * (a's layer & b's mask) or (b's layer & a's mask). Nothing is pushed apart by it: how far
 * apart would part a pair is read (get_push), and a body (wgf_body2d.h) is stopped by solid
 * ones. Only colliders under the same parent actor are compared, found by a sweep of their
 * bounds (a few thousand at once).
 *
 * Its shape: a circle (a sphere: its z counts against another circle's), its radius scaled
 * by the larger of the actor's scale's x and y; or, on a 2D stage's plane (x and y; z
 * ignored), a rectangle, a convex polygon, or a segment, scaled by the actor's scale and
 * turned by its turn about z. Each is about the actor's position moved by its offset
 * (scaled and turned with it). Defaults: a circle of radius 1, no offset, layer 1, mask
 * everything (-1), enabled. Every call is false (or 0) for an actor without a collider.
 */
export const WGF_COLLIDER_SHAPE_CIRCLE = 0;
export const WGF_COLLIDER_SHAPE_RECTANGLE = 1;
export const WGF_COLLIDER_SHAPE_POLYGON = 2;
export const WGF_COLLIDER_SHAPE_SEGMENT = 3;

/**
 * Screens and scene flow: a game as a stack of screens (a title, play, a pause menu, game
 * over), helix-legacy's scene flow (Flow, Transition, Loader, LoadingScreen) without its
 * callbacks. A screen is an actor (a game's behaviors for it go on it) with its stages, 2D
 * and 3D, added to it in the order they draw (stages are always roots: they belong to it
 * without being its children); everything else of its hangs under them.
 *
 * The stack: push puts a screen on top, pop takes the top off, replace swaps the top for
 * another. The top runs. A screen under one that pauses (the default) is paused
 * (wgf_actor_set_paused: drawn, frozen), it and its stages; one under one that doesn't (a
 * HUD laid over play) runs on. A screen off the stack is switched off and paused, it and its
 * stages (wgf_actor_set_enabled: not drawn, nothing under them moving), kept for the program
 * to push again or destroy. draw
 * draws what is shown: from the bottom up, each screen's stages in their order, but none
 * under an opaque one (the default), then the transition's cover.
 *
 * A change runs through the transition set (none to start: at once). It covers the frame
 * over half its seconds, makes the change at the middle, and uncovers over the other half,
 * each half on the ease. A screen given assets to wait for (set_assets: a group,
 * wgf_asset.h), or set to wait for every load pending (set_wait_loads: the textures and
 * meshes made as it was built), is changed to only once they have settled: the stack held
 * covered meanwhile, with the loading screen (set_loading_screen) drawn over the cover and
 * its progress readable. While one runs, another change is refused (false).
 *
 * Each change is told as world events (wgf_world.h): SCREEN_ENTER for the screen that
 * comes to the top, SCREEN_EXIT for the one that leaves it (pushed under, popped, or
 * replaced), each with the other screen (0 for none) as its second; a binding's behaviors
 * on a screen hear them.
 */
export const WGF_TRANSITION_NONE = 0;
export const WGF_TRANSITION_FADE = 1;
export const WGF_TRANSITION_SLIDE_LEFT = 2;
export const WGF_TRANSITION_SLIDE_RIGHT = 3;
export const WGF_TRANSITION_SLIDE_UP = 4;
export const WGF_TRANSITION_SLIDE_DOWN = 5;
export const WGF_TRANSITION_WIPE = 6;
export const WGF_TRANSITION_IRIS = 7;

/**
 * The simulation as a whole: libwgf's systems over the actors' components
 * (wgf_component.h), the events they raise, and the simulated actors written out as text;
 * the actors with a behavior or a component are found by wgf_actor_find_with_behavior
 * (wgf_behavior.h) and wgf_actor_find_with_component (wgf_component.h).
 *
 * Each tick, as it begins, every simulated actor's transform is kept as it is; after the
 * program's tick the systems run in this order: lifetimes count down (an actor whose time is
 * up destroyed), motion moves each actor by its velocity and spin (damped, its speed
 * capped), bounds wrap, clamp, or destroy what has left its rectangle, and colliders find
 * the overlaps. Each frame a simulated actor is drawn between its last two ticks'
 * transforms.
 *
 * Events are what the program's behaviors are told (wgf_behavior.h), queued as they
 * happen and taken by the program, in order, four ints each (the event and three more):
 *
 *   CREATED          a behavior added: its actor, its id, 0
 *   DESTROYED        a behavior removed, or its actor gone: its actor (stale by then, a name
 *                    for what it was), its id, 0
 *   TRIGGER_ENTER    two colliders starting to overlap, told to each: the actor, the other,
 *                    and the other's collider layer as they met
 *   TRIGGER_EXIT     and ceasing to
 *   CONTACT_BEGIN    two solid bodies beginning to touch (wgf_body.h), told to each: the
 *                    actor, the other, and the other's body layer
 *   CONTACT_END      and ceasing to
 *   SCREEN_ENTER     a screen coming to the top of the stack (wgf_screen.h): the screen,
 *                    the one it covers or replaced (0 for none)
 *   SCREEN_EXIT      a screen leaving the top: the screen, the one now there (0 for none)
 *
 * An actor destroyed while it overlaps another raises no TRIGGER_EXIT. Events taken in a
 * batch can name an actor the program destroyed while handling an earlier one of the
 * batch: a binding's runtime drops a trigger whose actor or other is gone by then. Nothing is called
 * back: a binding takes them at its tick's start and calls its behaviors itself. At most
 * 65536 wait; past that the oldest are dropped, warned once.
 */
export const WGF_WORLD_EVENT_NONE = 0;
export const WGF_WORLD_EVENT_CREATED = 1;
export const WGF_WORLD_EVENT_DESTROYED = 2;
export const WGF_WORLD_EVENT_TRIGGER_ENTER = 3;
export const WGF_WORLD_EVENT_TRIGGER_EXIT = 4;
export const WGF_WORLD_EVENT_CONTACT_BEGIN = 5;
export const WGF_WORLD_EVENT_CONTACT_END = 6;
export const WGF_WORLD_EVENT_SCREEN_ENTER = 7;
export const WGF_WORLD_EVENT_SCREEN_EXIT = 8;

/**
 * A body (WGF_COMPONENT_BODY, wgf_component.h): an actor in the physics world
 * (wgf_physics.h), as a rigid shape. Defaults: dynamic, a box of 1 by 1 by 1, its mass from
 * its size (1000 kg a cubic meter), friction 0.5, no bounce, damping of 0.05, layer 1,
 * mask every layer. Friction, bounce, and damping take effect at once, its motion kept (a
 * car's drag on grass, set as it goes); its other settings take effect at the next tick,
 * when the world's body is made again from them, at rest: set them together, before the
 * first tick, as a scene does.
 *
 * The actor's transform is the body's: where the world moves a dynamic body, each tick,
 * the actor is set; a transform the program sets puts the body there (a static or
 * dynamic one jumps; a kinematic one is moved there over the tick, pushing what it meets).
 * A box's, sphere's, or capsule's size isn't scaled with its actor; a convex or mesh shape
 * is read from the models at and under the actor, as they are drawn: the actor's own scale
 * and each model's place under it included. Its place is in its 3D
 * stage's space, the actor anywhere in the stage's tree. The calls are false (or 0) for an actor without a
 * body.
 */
export const WGF_BODY_TYPE_STATIC = 0;
export const WGF_BODY_TYPE_DYNAMIC = 1;
export const WGF_BODY_TYPE_KINEMATIC = 2;
export const WGF_BODY_TYPE_SENSOR = 3;
export const WGF_BODY_TYPE_CHARACTER = 4;

export const WGF_BODY_SHAPE_BOX = 0;
export const WGF_BODY_SHAPE_SPHERE = 1;
export const WGF_BODY_SHAPE_CAPSULE = 2;
export const WGF_BODY_SHAPE_CONVEX = 3;
export const WGF_BODY_SHAPE_MESH = 4;

/**
 * A wheeled vehicle (WGF_COMPONENT_VEHICLE, wgf_component.h) on an actor with a dynamic
 * body (wgf_body.h): wheels on springs, an engine, an automatic gearbox, and differentials,
 * driven by the program's intent (set_input), each tick, in the physics world
 * (wgf_physics.h). It faces its actor's +z, +y up.
 *
 * Its wheels are actors under it, given in left and right pairs, front first: where each
 * is as the vehicle is made is where it attaches (its spring at rest), and each tick it is
 * set where the wheel is, steered, sprung, and turning about its own x, so a model under
 * it with its axle along x shows the wheel. The first pair steers. Defaults: no wheels, an engine of 500 Nm to 6000 rpm,
 * Jolt's gear ratios, rear drive, wheels of 0.3 m by 0.2 m, 0.3 m of spring travel at 1.5
 * Hz damped by half, 0.5 radians of steering, grip 1. Its settings take effect at the next
 * tick, when it is made again from them (at rest), as a body's are; reset puts it at rest
 * where it is (its anti-roll bars take a change at once). The calls are false (or 0) for
 * an actor without a vehicle.
 */
export const WGF_VEHICLE_DRIVE_FRONT = 0;
export const WGF_VEHICLE_DRIVE_REAR = 1;
export const WGF_VEHICLE_DRIVE_ALL = 2;

/**
 * Game UI, immediate mode: each frame the program describes the UI as it is now --
 * boxes, panels, labels, buttons, progress bars -- between wgf_ui_begin and wgf_ui_end, inside the
 * frame callback; libwgf lays it out (Clay), answers what the pointer, the keys, and the
 * pads did to it, and draws it at wgf_ui_end, over what the frame drew before.
 *
 * The screen is the root: a column of everything given, centered both ways. A box lays
 * its children out in a column or a row, sized to fit them unless set otherwise. A
 * button's answer comes from where things were in the frame before, as with every
 * immediate-mode UI: a UI that moves under the pointer is answered where it was.
 *
 * Focus: one button at a time has it, by its id. Arrow keys, Tab and Shift+Tab, and a
 * pad's D-pad move it through the frame's buttons in the order they were given (the
 * first press of one puts it on the first or the last); Enter, Space, or a pad's south
 * button activates it. The pointer activates the button it is pressed and released over,
 * and gives it the focus; a focus moved by keys or pads is drawn, one given by the
 * pointer isn't. A focused button that isn't given in a frame loses the focus.
 *
 * The UI says when it has the pointer (wgf_input_set_pointer_captured): while the
 * pointer is over a panel, a button, or a box with a color, or a press on a button is
 * held; and the keyboard (wgf_input_set_keyboard_captured) while a button has the focus.
 * A frame without wgf_ui_end lets both go.
 *
 * Ids name boxes, panels, and buttons, and are unique in a frame (Clay refuses a
 * second, logged); a box or panel may have none (NULL or ""). Text is copied: it may
 * change or go after the call. Every call but the style's is false outside a begun UI.
 */
export const WGF_UI_DIRECTION_COLUMN = 0;
export const WGF_UI_DIRECTION_ROW = 1;

